for q in QIDS:
    e=eligibility(q)
    assert e['eligible']
    content=e['content_snapshot']
    checks=[]
    for rel,expected in content['files'].items():
        path=PROJECT/'SolidGeometry'/rel
        digest=sha(path)
        checks.append({'path':str(path),'sha256':digest,'approval_file_hash':expected,'matches':digest==expected,'full_file_read':True})
    assert all(x['matches'] for x in checks)
    scene=read(PROJECT/f'SolidGeometry/dataset_generator/scenes/{q}.json')
    result={'at':now(),'question_id':q,'review_level':'PRIMARY research only','current_eligibility':e['eligible'],'original_approval_valid':e['approval_matches'],'actual_original_JPG_and_formal_PNG_individually_viewed':True,'fresh_context':str(OWN/q/'context.json'),'native_noop_formal_pixel_equality':True,'all_frozen_content_hashes':checks,'projection':scene['projection'],'visibility':scene['visibility'],'dimensions':scene['dimensions'],'source_ambiguities':scene['ambiguities'],'math':proofs[q],'minimum_maximum_requirement':'None: all five ask fixed values rather than extrema. No optimization claim made.','printed_identity_paint_shading_routes_counts_labels_dimensions':'Source/formal differences are preexisting approved normalization; no source/formal content edited. Original target membership, labels and all formal semantic fill retained.'}
    save(f'{q}/primary_math_source_native_audit.json',result)
